<script>
// Function to start the counter when an element is in the viewport
function startCounterWhenVisible(entries, observer1) { // Change the observer variable name
  entries.forEach((entry) => {
    if (entry.isIntersecting) {
      const counterElement = entry.target.querySelector('span');
      const targetValue = parseInt(counterElement.textContent, 10);
      let currentValue = 0;

      const counterInterval = setInterval(() => {
        if (currentValue < targetValue) {
          currentValue += Math.ceil(targetValue / 100); // Adjust the speed of counting
          counterElement.textContent = currentValue;
        } else {
          clearInterval(counterInterval);
        }
      }, 20);

      // Unobserve the element to stop the counter when done
      observer1.unobserve(entry.target); // Change the observer variable name
    }
  });
}

// Create an Intersection Observer instance
const observer1 = new IntersectionObserver(startCounterWhenVisible, {
  threshold: 0.2, // Adjust this threshold value as needed
});

// Observe each section you want to trigger the counter for
document.querySelectorAll('.ttm-fid').forEach((section) => {
  observer1.observe(section); // Change the observer variable name
});
</script>
