          counterElement.textContent = currentValue;
        } else {
          clearInterval(counterInterval);
        }
      }, 100); // Adjust the interval duration for slower counting

      // Unobserve the element to stop the counter when done
      observer2.unobserve(entry.target); // Change the observer variable name
    }
  });
}

// Create an Intersection Observer instance
const observer2 = new IntersectionObserver(startCounterWhenVisible, {
  threshold: 0.2, // Adjust this threshold value as needed
});

// Observe the section with the class "ttm-fid" to trigger the counter
observer2.observe(document.querySelector('.ttm-fid')); // Change the observer variable name
</script>


